"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[5591],{64084:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>h});var s=t(74848),o=t(28453);const i={slug:"L Has Landed - A New Runtime for k and q Enters the Scene",title:"L Has Landed - A New Runtime for k and q Enters the Scene",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","DefconQ","L"]},r=void 0,a={permalink:"/blog/L Has Landed - A New Runtime for k and q Enters the Scene",source:"@site/blog/2026-07-07-L-just-landed/index.md",title:"L Has Landed - A New Runtime for k and q Enters the Scene",description:"Not Only the Weather Is Heating Up\u2026",date:"2026-07-07T00:00:00.000Z",tags:[{label:"kdb/q",permalink:"/blog/tags/kdb-q"},{label:"DefconQ",permalink:"/blog/tags/defcon-q"},{label:"L",permalink:"/blog/tags/l"}],readingTime:4.325,hasTruncateMarker:!0,authors:[{name:"Alexander Unterrainer",title:"DefconQ, KDB/Q Developer, Consultant",url:"https://github.com/AUnterrainer",imageURL:"/img/alex.jpeg",key:"alexander"}],frontMatter:{slug:"L Has Landed - A New Runtime for k and q Enters the Scene",title:"L Has Landed - A New Runtime for k and q Enters the Scene",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","DefconQ","L"]},unlisted:!1,nextItem:{title:"When Markets Never Sleep - Extended Hours, Odd Lots, and the Infrastructure Implications of Always-On Markets",permalink:"/blog/When Markets Never Sleep - Extended Hours, Odd Lots, and the Infrastructure Implications of Always-On Markets"}},l={authorsImageUrls:[void 0]},h=[{value:"Not Only the Weather Is Heating Up\u2026",id:"not-only-the-weather-is-heating-up",level:2},{value:"Why Build Another Runtime?",id:"why-build-another-runtime",level:2},{value:"Performance Looks\u2026 Interesting",id:"performance-looks-interesting",level:2},{value:"More Choice Is Good for Everyone",id:"more-choice-is-good-for-everyone",level:2},{value:"What Else Is Brewing?",id:"what-else-is-brewing",level:2},{value:"I&#39;ll Be Keeping a Close Eye on This One",id:"ill-be-keeping-a-close-eye-on-this-one",level:2}];function d(e){const n={a:"a",h2:"h2",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.h2,{id:"not-only-the-weather-is-heating-up",children:"Not Only the Weather Is Heating Up\u2026"}),"\n",(0,s.jsxs)(n.p,{children:["Not only have the temperatures been rising this summer, but so has the market for exciting new projects in the k and q ecosystem. While I'm aware of several groups quietly working on some very interesting ideas behind the scenes, L-Labs a new entity founded by K/Q veteran and former HFT engineer ",(0,s.jsx)(n.a,{href:"https://www.linkedin.com/in/jacobloveless/",children:(0,s.jsx)(n.strong,{children:"Jacob Loveless"})}),", is the first to bring something new to market."]}),"\n",(0,s.jsxs)(n.p,{children:["Meet ",(0,s.jsx)(n.a,{href:"https://lv1.sh",children:(0,s.jsx)(n.strong,{children:"L"})}),"."]}),"\n",(0,s.jsx)(n.p,{children:"A brand-new runtime for k and q that has just become publicly available, with the ambitious goal of rethinking how k and q applications are executed."}),"\n",(0,s.jsx)(n.p,{children:"As someone who spends a large amount of time looking at everything happening around the KDB/Q ecosystem, it's always exciting to see innovation emerge, especially when it comes from someone who has been working with the language for years."}),"\n",(0,s.jsx)(n.h2,{id:"why-build-another-runtime",children:"Why Build Another Runtime?"}),"\n",(0,s.jsx)(n.p,{children:"It's a fair question."}),"\n",(0,s.jsx)(n.p,{children:"After all, q has been around for decades, has powered some of the world's largest financial institutions, and remains one of the fastest technologies available for time-series analytics.\nSo why build another runtime?\nJacob's motivation is refreshingly straightforward."}),"\n",(0,s.jsxs)(n.p,{children:["As he explains in his ",(0,s.jsx)(n.a,{href:"https://lv1.sh/blog/why-l/",children:(0,s.jsx)(n.strong,{children:"Why L? article"})}),", the goal wasn't to replace existing tools for the sake of replacing them. It was to build a modern runtime that explores different implementation choices, removes historical constraints where possible, and provides a fresh foundation for future development. Rather than simply recreating the past, L is an experiment in how a modern k and q runtime could look today."]}),"\n",(0,s.jsx)(n.p,{children:"Projects like this are healthy for an ecosystem."}),"\n",(0,s.jsx)(n.p,{children:"They challenge assumptions."}),"\n",(0,s.jsx)(n.p,{children:"They encourage experimentation."}),"\n",(0,s.jsx)(n.p,{children:"And they often introduce ideas that eventually influence everyone."}),"\n",(0,s.jsx)(n.h2,{id:"performance-looks-interesting",children:"Performance Looks\u2026 Interesting"}),"\n",(0,s.jsx)(n.p,{children:"One of the first things that caught my eye was the benchmark section.\nL has been benchmarked across a variety of workloads and, at least in the published results, performs extremely well, often outperforming many other language runtimes in those tests. It's an impressive showing and certainly suggests there's some serious engineering under the hood."}),"\n",(0,s.jsx)(n.p,{children:"Of course, benchmarks always deserve a healthy dose of context."}),"\n",(0,s.jsx)(n.p,{children:"Different benchmarks measure different things, and synthetic workloads don't necessarily translate directly into production systems. The workloads you care about might look very different from those used in published comparisons.\nFor those of us working with production KDB/Q systems, the natural question is how L behaves on the kinds of real-world problems we care about: large in-memory databases, tickerplants, gateways, IPC-heavy applications, historical queries, and high-throughput market data processing."}),"\n",(0,s.jsx)(n.p,{children:"That's still something the community will have to explore over time.\nBut regardless of where those comparisons ultimately land, it's encouraging to see a new runtime pushing performance and introducing fresh implementation ideas."}),"\n",(0,s.jsx)(n.h2,{id:"more-choice-is-good-for-everyone",children:"More Choice Is Good for Everyone"}),"\n",(0,s.jsx)(n.p,{children:"Perhaps the most exciting aspect of L isn't a benchmark chart."}),"\n",(0,s.jsx)(n.p,{children:"It's the fact that somebody decided to build something new."}),"\n",(0,s.jsx)(n.p,{children:"For a long time, the k and q ecosystem has been relatively quiet when it comes to alternative runtimes and implementations. Seeing fresh ideas emerge lowers the barrier for experimentation and opens up entirely new opportunities for developers, researchers, and companies interested in the language.\nCompetition drives innovation."}),"\n",(0,s.jsx)(n.p,{children:"New implementations often lead to new tooling. Different implementation strategies expose different strengths. Three decades have seen several implementations of k, none as fast as k4. L has supported commercial systems for a decade. And it claims to be significantly faster than k4. And even if they never become the dominant runtime, they frequently inspire improvements across the wider ecosystem.\nThat's good news for everyone who enjoys working with vector programming languages."}),"\n",(0,s.jsx)(n.h2,{id:"what-else-is-brewing",children:"What Else Is Brewing?"}),"\n",(0,s.jsxs)(n.p,{children:["L certainly isn't the only exciting project currently in the works. Behind the scenes, several teams are quietly building new languages, tools, runtimes, libraries, and ideas that have the potential to shape the future of the k and q ecosystem. Some are still under wraps, others are getting closer to seeing the light of day.\nAs always, ",(0,s.jsx)(n.strong,{children:"DefconQ"})," aims to stay at the forefront of everything happening in the community. I'll be following these developments closely and sharing them here as soon as they're ready to go public.\nSo if you'd like to stay ahead of the curve, make sure to follow DefconQ. The easiest way is to subscribe to the ",(0,s.jsx)(n.a,{href:"https://defconq.substack.com",children:(0,s.jsx)(n.strong,{children:"free newsletter"})})," and have every new article delivered straight to your inbox, or follow me on ",(0,s.jsx)(n.a,{href:"https://www.linkedin.com/in/alexanderunterrainer/",children:(0,s.jsx)(n.strong,{children:"LinkedIn"})})," where I regularly share the latest news, tutorials, and developments from across the ecosystem."]}),"\n",(0,s.jsx)(n.p,{children:"Because if this summer has shown us anything, it's that the k and q world is far from standing still."}),"\n",(0,s.jsx)(n.h2,{id:"ill-be-keeping-a-close-eye-on-this-one",children:"I'll Be Keeping a Close Eye on This One"}),"\n",(0,s.jsx)(n.p,{children:"It's still very early days, and only time will tell how L evolves and where it ultimately fits within the ecosystem.\nBut one thing is certain: it's one of the most interesting developments in the k and q world this year.\nI'll definitely be keeping a close eye on the project, experimenting with it, and following its progress as it matures.\nIf you're curious yourself, I'd encourage you to take a look, play around with it, and form your own opinion.\nAs always, I'll keep you posted as I learn more."}),"\n",(0,s.jsx)(n.p,{children:"Stay tuned."})]})}function c(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>r,x:()=>a});var s=t(96540);const o={},i=s.createContext(o);function r(e){const n=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),s.createElement(i.Provider,{value:n},e.children)}}}]);